1	import { useState } from "react";
2	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
3	import { Button } from "@/components/ui/button";
4	import { Input } from "@/components/ui/input";
5	import { Label } from "@/components/ui/label";
6	import { Badge } from "@/components/ui/badge";
7	import { toast } from "sonner";
8	import { Key, Copy, Eye, EyeOff, Plus, Trash2, Webhook, Code2 } from "lucide-react";
9	import { cn } from "@/lib/utils";
10	
11	interface ApiKey {
12	  id: string;
13	  label: string;
14	  key: string;
15	  createdAt: string;
16	}
17	
18	interface WebhookEntry {
19	  id: string;
20	  url: string;
21	  events: string[];
22	  active: boolean;
23	}
24	
25	const STORAGE_KEY = "rankora_api_keys";
26	const WEBHOOK_STORAGE_KEY = "rankora_webhooks";
27	
28	function generateApiKey(): string {
29	  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
30	  const prefix = "rk_live_";
31	  let result = "";
32	  for (let i = 0; i < 32; i++) {
33	    result += chars.charAt(Math.floor(Math.random() * chars.length));
34	  }
35	  return prefix + result;
36	}
37	
38	function loadKeys(): ApiKey[] {
39	  try {
40	    return JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
41	  } catch { return []; }
42	}
43	
44	function saveKeys(keys: ApiKey[]) {
45	  localStorage.setItem(STORAGE_KEY, JSON.stringify(keys));
46	}
47	
48	function loadWebhooks(): WebhookEntry[] {
49	  try {
50	    return JSON.parse(localStorage.getItem(WEBHOOK_STORAGE_KEY) || "[]");
51	  } catch { return []; }
52	}
53	
54	function saveWebhooks(hooks: WebhookEntry[]) {
55	  localStorage.setItem(WEBHOOK_STORAGE_KEY, JSON.stringify(hooks));
56	}
57	
58	const WEBHOOK_EVENTS = [
59	  "job.created",
60	  "ranking.completed",
61	  "candidate.applied",
62	  "candidate.rejected",
63	  "interview.scheduled",
64	];
65	
66	const ApiKeysCard = () => {
67	  const [keys, setKeys] = useState<ApiKey[]>(loadKeys);
68	  const [webhooks, setWebhooks] = useState<WebhookEntry[]>(loadWebhooks);
69	  const [newLabel, setNewLabel] = useState("");
70	  const [revealedId, setRevealedId] = useState<string | null>(null);
71	  const [newWebhookUrl, setNewWebhookUrl] = useState("");
72	
73	  const createKey = () => {
74	    const label = newLabel.trim() || "My API Key";
75	    const newKey: ApiKey = {
76	      id: crypto.randomUUID(),
77	      label,
78	      key: generateApiKey(),
79	      createdAt: new Date().toISOString(),
80	    };
81	    const updated = [...keys, newKey];
82	    setKeys(updated);
83	    saveKeys(updated);
84	    setNewLabel("");
85	    setRevealedId(newKey.id);
86	    toast.success("API key created — copy it now, it won't be shown again in full.");
87	  };
88	
89	  const deleteKey = (id: string) => {
90	    const updated = keys.filter((k) => k.id !== id);
91	    setKeys(updated);
92	    saveKeys(updated);
93	    toast.success("API key deleted");
94	  };
95	
96	  const copyKey = (key: string) => {
97	    navigator.clipboard.writeText(key);
98	    toast.success("API key copied");
99	  };
100	
101	  const maskKey = (key: string) => {
102	    return key.slice(0, 12) + "..." + key.slice(-4);
103	  };
104	
105	  const addWebhook = () => {
106	    const url = newWebhookUrl.trim();
107	    if (!url) return;
108	    try {
109	      new URL(url);
110	    } catch {
111	      toast.error("Please enter a valid URL");
112	      return;
113	    }
114	    const entry: WebhookEntry = {
115	      id: crypto.randomUUID(),
116	      url,
117	      events: ["ranking.completed"],
118	      active: true,
119	    };
120	    const updated = [...webhooks, entry];
121	    setWebhooks(updated);
122	    saveWebhooks(updated);
123	    setNewWebhookUrl("");
124	    toast.success("Webhook endpoint added");
125	  };
126	
127	  const removeWebhook = (id: string) => {
128	    const updated = webhooks.filter((w) => w.id !== id);
129	    setWebhooks(updated);
130	    saveWebhooks(updated);
131	    toast.success("Webhook removed");
132	  };
133	
134	  return (
135	    <div className="space-y-6">
136	      {/* API Keys */}
137	      <Card className="border border-border/60 shadow-sm">
138	        <CardHeader className="pb-3">
139	          <div className="flex items-center gap-2">
140	            <Key className="h-5 w-5 text-primary" />
141	            <CardTitle className="text-sm font-semibold">API Keys</CardTitle>
142	          </div>
143	          <CardDescription>
144	            Use API keys to integrate Rankora with your tools. Keys have full access to your account.
145	          </CardDescription>
146	        </CardHeader>
147	        <CardContent className="space-y-4">
148	          {/* Existing keys */}
149	          {keys.length > 0 && (
150	            <div className="space-y-2">
151	              {keys.map((k) => (
152	                <div key={k.id} className="flex items-center gap-2 rounded-lg border border-border/60 px-3 py-2">
153	                  <div className="flex-1 min-w-0">
154	                    <p className="text-sm font-medium text-foreground">{k.label}</p>
155	                    <code className="text-xs text-muted-foreground font-mono">
156	                      {revealedId === k.id ? k.key : maskKey(k.key)}
157	                    </code>
158	                  </div>
159	                  <Button
160	                    variant="ghost"
161	                    size="sm"
162	                    className="h-7 w-7 p-0"
163	                    onClick={() => setRevealedId(revealedId === k.id ? null : k.id)}
164	                  >
165	                    {revealedId === k.id ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
166	                  </Button>
167	                  <Button variant="ghost" size="sm" className="h-7 w-7 p-0" onClick={() => copyKey(k.key)}>
168	                    <Copy className="h-3.5 w-3.5" />
169	                  </Button>
170	                  <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive" onClick={() => deleteKey(k.id)}>
171	                    <Trash2 className="h-3.5 w-3.5" />
172	                  </Button>
173	                </div>
174	              ))}
175	            </div>
176	          )}
177	
178	          {/* Create new key */}
179	          <div className="flex items-center gap-2">
180	            <Input
181	              value={newLabel}
182	              onChange={(e) => setNewLabel(e.target.value)}
183	              placeholder="Key label (e.g. Zapier, n8n)"
184	              className="h-9 text-sm"
185	            />
186	            <Button size="sm" className="h-9 gap-1.5 shrink-0" onClick={createKey}>
187	              <Plus className="h-3.5 w-3.5" /> Generate Key
188	            </Button>
189	          </div>
190	        </CardContent>
191	      </Card>
192	
193	      {/* Webhooks */}
194	      <Card className="border border-border/60 shadow-sm">
195	        <CardHeader className="pb-3">
196	          <div className="flex items-center gap-2">
197	            <Webhook className="h-5 w-5 text-primary" />
198	            <CardTitle className="text-sm font-semibold">Webhooks</CardTitle>
199	          </div>
200	          <CardDescription>
201	            Receive real-time notifications when events happen in your account.
202	          </CardDescription>
203	        </CardHeader>
204	        <CardContent className="space-y-4">
205	          {/* Available events */}
206	          <div>
207	            <Label className="text-xs font-medium text-muted-foreground mb-2 block">Available Events</Label>
208	            <div className="flex flex-wrap gap-1.5">
209	              {WEBHOOK_EVENTS.map((event) => (
210	                <Badge key={event} variant="secondary" className="text-[11px] font-mono">
211	                  {event}
212	                </Badge>
213	              ))}
214	            </div>
215	          </div>
216	
217	          {/* Existing webhooks */}
218	          {webhooks.length > 0 && (
219	            <div className="space-y-2">
220	              {webhooks.map((wh) => (
221	                <div key={wh.id} className="flex items-center gap-2 rounded-lg border border-border/60 px-3 py-2">
222	                  <div className={cn("h-2 w-2 rounded-full shrink-0", wh.active ? "bg-emerald-500" : "bg-muted-foreground/30")} />
223	                  <code className="text-xs text-foreground font-mono flex-1 truncate">{wh.url}</code>
224	                  <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive" onClick={() => removeWebhook(wh.id)}>
225	                    <Trash2 className="h-3.5 w-3.5" />
226	                  </Button>
227	                </div>
228	              ))}
229	            </div>
230	          )}
231	
232	          {/* Add webhook */}
233	          <div className="flex items-center gap-2">
234	            <Input
235	              value={newWebhookUrl}
236	              onChange={(e) => setNewWebhookUrl(e.target.value)}
237	              placeholder="https://your-app.com/webhook"
238	              className="h-9 text-sm font-mono"
239	            />
240	            <Button size="sm" className="h-9 gap-1.5 shrink-0" onClick={addWebhook}>
241	              <Plus className="h-3.5 w-3.5" /> Add
242	            </Button>
243	          </div>
244	        </CardContent>
245	      </Card>
246	
247	      {/* API Docs quick reference */}
248	      <Card className="border border-border/60 shadow-sm">
249	        <CardHeader className="pb-3">
250	          <div className="flex items-center gap-2">
251	            <Code2 className="h-5 w-5 text-primary" />
252	            <CardTitle className="text-sm font-semibold">API Quick Reference</CardTitle>
253	          </div>
254	        </CardHeader>
255	        <CardContent>
256	          <div className="rounded-lg bg-muted/40 p-4 space-y-3 text-xs font-mono">
257	            <div>
258	              <p className="text-muted-foreground mb-1"># List your jobs</p>
259	              <p className="text-foreground">GET /api/v1/jobs</p>
260	            </div>
261	            <div>
262	              <p className="text-muted-foreground mb-1"># Get candidates for a job</p>
263	              <p className="text-foreground">GET /api/v1/jobs/:id/candidates</p>
264	            </div>
265	            <div>
266	              <p className="text-muted-foreground mb-1"># Create a new job</p>
267	              <p className="text-foreground">POST /api/v1/jobs</p>
268	            </div>
269	            <div>
270	              <p className="text-muted-foreground mb-1"># Authentication header</p>
271	              <p className="text-foreground">Authorization: Bearer rk_live_...</p>
272	            </div>
273	          </div>
274	          <p className="text-xs text-muted-foreground mt-3">
275	            Full API documentation available at <span className="font-medium text-foreground">docs.rankora.co/api</span>
276	          </p>
277	        </CardContent>
278	      </Card>
279	    </div>
280	  );
281	};
282	
283	export default ApiKeysCard;
