import { useState, useMemo } from "react";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Checkbox } from "@/components/ui/checkbox";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import {
  Linkedin,
  CalendarDays,
  Zap,
  FileSearch,
  Mail,
  Building2,
  Briefcase,
  MessageCircle,
  Globe,
  Webhook,
  Code2,
  Hash,
  Star,
  TreePine,
  LayoutGrid,
  Search,
  Copy,
  Key,
  BookOpen,
  ChevronRight,
  Plus,
  Trash2,
  Eye,
  EyeOff,
  Users,
  Send,
  CheckCircle2,
  XCircle,
} from "lucide-react";
import ApiKeysCard from "@/components/settings/ApiKeysCard";

// ─── Types ────────────────────────────────────────────────────────────────────

type IntegrationStatus = "connected" | "available" | "coming_soon";

interface Integration {
  id: string;
  name: string;
  description: string;
  icon: React.ReactNode;
  iconBg: string;
  status: IntegrationStatus;
}

// ─── Integration Definitions ──────────────────────────────────────────────────

const INTEGRATIONS: Integration[] = [
  // Communication — connected
  {
    id: "whatsapp",
    name: "WhatsApp",
    description: "Send interview invites and candidate updates via WhatsApp messages.",
    icon: <MessageCircle className="h-5 w-5 text-[#25D366]" />,
    iconBg: "bg-[#25D366]/10",
    status: "connected",
  },
  {
    id: "resend",
    name: "Email (Resend)",
    description: "Send transactional emails for ranking notifications and resume ingestion.",
    icon: <Mail className="h-5 w-5 text-blue-600" />,
    iconBg: "bg-blue-500/10",
    status: "connected",
  },
  // Job Boards — connected / available
  {
    id: "google-jobs",
    name: "Google Jobs",
    description: "Post jobs directly to Google Search's job listings for wider reach.",
    icon: <Globe className="h-5 w-5 text-[#4285F4]" />,
    iconBg: "bg-[#4285F4]/10",
    status: "connected",
  },
  {
    id: "indeed",
    name: "Indeed",
    description: "Import resumes directly from Indeed job postings into Rankora.",
    icon: <FileSearch className="h-5 w-5 text-[#2164F3]" />,
    iconBg: "bg-[#2164F3]/10",
    status: "connected",
  },
  // Developer — connected
  {
    id: "rest-api",
    name: "REST API",
    description: "Programmatic access to all Rankora data via a documented REST API.",
    icon: <Code2 className="h-5 w-5 text-primary" />,
    iconBg: "bg-primary/10",
    status: "connected",
  },
  {
    id: "webhooks",
    name: "Webhooks",
    description: "Receive real-time HTTP push events when candidates are ranked or applied.",
    icon: <Webhook className="h-5 w-5 text-violet-600" />,
    iconBg: "bg-violet-500/10",
    status: "connected",
  },
  // Available
  {
    id: "linkedin",
    name: "LinkedIn",
    description: "Import candidates and post jobs directly to LinkedIn.",
    icon: <Linkedin className="h-5 w-5 text-[#0A66C2]" />,
    iconBg: "bg-[#0A66C2]/10",
    status: "available",
  },
  {
    id: "zapier",
    name: "Zapier",
    description: "Connect Rankora with 5,000+ apps via powerful no-code automations.",
    icon: <Zap className="h-5 w-5 text-[#FF4A00]" />,
    iconBg: "bg-[#FF4A00]/10",
    status: "available",
  },
  // Coming Soon
  {
    id: "slack",
    name: "Slack",
    description: "Get notifications for new applications and rankings in your Slack workspace.",
    icon: <Hash className="h-5 w-5 text-[#4A154B]" />,
    iconBg: "bg-[#4A154B]/10",
    status: "coming_soon",
  },
  {
    id: "ziprecruiter",
    name: "ZipRecruiter",
    description: "Distribute job postings to ZipRecruiter's candidate network.",
    icon: <FileSearch className="h-5 w-5 text-[#FF6B35]" />,
    iconBg: "bg-[#FF6B35]/10",
    status: "coming_soon",
  },
  {
    id: "glassdoor",
    name: "Glassdoor",
    description: "Post and manage job listings on Glassdoor's platform.",
    icon: <Star className="h-5 w-5 text-[#0CAA41]" />,
    iconBg: "bg-[#0CAA41]/10",
    status: "coming_soon",
  },
  {
    id: "monster",
    name: "Monster",
    description: "Reach millions of job seekers by posting directly to Monster.",
    icon: <Briefcase className="h-5 w-5 text-[#6600CC]" />,
    iconBg: "bg-[#6600CC]/10",
    status: "coming_soon",
  },
  {
    id: "google-calendar",
    name: "Google Calendar",
    description: "Schedule interviews and sync availability with candidates automatically.",
    icon: <CalendarDays className="h-5 w-5 text-[#4285F4]" />,
    iconBg: "bg-[#4285F4]/10",
    status: "coming_soon",
  },
  {
    id: "outlook-calendar",
    name: "Outlook Calendar",
    description: "Schedule and manage interviews through Microsoft Outlook Calendar.",
    icon: <CalendarDays className="h-5 w-5 text-[#0078D4]" />,
    iconBg: "bg-[#0078D4]/10",
    status: "coming_soon",
  },
  {
    id: "google-workspace",
    name: "Google Workspace",
    description: "Sync with Gmail, Google Drive, and Google Contacts for seamless hiring.",
    icon: <Mail className="h-5 w-5 text-[#EA4335]" />,
    iconBg: "bg-[#EA4335]/10",
    status: "coming_soon",
  },
  {
    id: "ms-teams",
    name: "Microsoft Teams",
    description: "Team notifications and hiring collaboration inside Microsoft Teams.",
    icon: <Users className="h-5 w-5 text-[#6264A7]" />,
    iconBg: "bg-[#6264A7]/10",
    status: "coming_soon",
  },
  {
    id: "greenhouse",
    name: "Greenhouse",
    description: "Sync ranked candidates with your Greenhouse ATS pipeline.",
    icon: <Building2 className="h-5 w-5 text-[#24A47F]" />,
    iconBg: "bg-[#24A47F]/10",
    status: "coming_soon",
  },
  {
    id: "lever",
    name: "Lever",
    description: "Push top-ranked candidates directly into your Lever recruiting pipeline.",
    icon: <Briefcase className="h-5 w-5 text-[#5865F2]" />,
    iconBg: "bg-[#5865F2]/10",
    status: "coming_soon",
  },
  {
    id: "bamboohr",
    name: "BambooHR",
    description: "Sync new hires and candidate data with BambooHR HR software.",
    icon: <TreePine className="h-5 w-5 text-[#73AA1E]" />,
    iconBg: "bg-[#73AA1E]/10",
    status: "coming_soon",
  },
  {
    id: "workday",
    name: "Workday",
    description: "Enterprise HR and talent management integration for large teams.",
    icon: <LayoutGrid className="h-5 w-5 text-[#005CB9]" />,
    iconBg: "bg-[#005CB9]/10",
    status: "coming_soon",
  },
];

// Sort: connected → available → coming_soon
const STATUS_ORDER: Record<IntegrationStatus, number> = {
  connected: 0,
  available: 1,
  coming_soon: 2,
};

// ─── Integration Card (horizontal) ───────────────────────────────────────────

const IntegrationCard = ({ integration }: { integration: Integration }) => {
  const isConnected = integration.status === "connected";
  const isAvailable = integration.status === "available";
  const isSoon = integration.status === "coming_soon";

  const handleAction = () => {
    if (isConnected) {
      toast.info(`${integration.name} — configuration coming soon`);
    } else if (isAvailable) {
      toast.info(`${integration.name} setup guide coming soon`);
    }
  };

  return (
    <Card
      className={cn(
        "border border-border/60 shadow-sm transition-all hover:shadow-md",
        isConnected && "border-primary/20",
        isSoon && "opacity-50"
      )}
    >
      <CardContent className="p-5 flex items-start gap-4">
        {/* Icon */}
        <div className={cn("h-10 w-10 rounded-xl flex items-center justify-center shrink-0", integration.iconBg)}>
          {integration.icon}
        </div>

        {/* Text + badges */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <p className="text-sm font-semibold text-foreground">{integration.name}</p>
            {isConnected && (
              <Badge className="bg-emerald-50 text-emerald-700 border border-emerald-200 hover:bg-emerald-50 text-[10px] dark:bg-emerald-900/30 dark:text-emerald-400 dark:border-emerald-800">
                Connected
              </Badge>
            )}
            {isAvailable && (
              <Badge variant="outline" className="bg-blue-50 text-blue-700 border-blue-200 text-[10px] dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-800">
                Available
              </Badge>
            )}
            {isSoon && (
              <Badge variant="secondary" className="text-[10px]">
                Soon
              </Badge>
            )}
          </div>
          <p className="text-xs text-muted-foreground mt-1 leading-relaxed">{integration.description}</p>
        </div>

        {/* Action button */}
        {isConnected && (
          <Button
            variant="ghost"
            size="sm"
            className="h-8 text-xs shrink-0 text-muted-foreground"
            onClick={handleAction}
          >
            Configure
          </Button>
        )}
        {isAvailable && (
          <Button
            variant="outline"
            size="sm"
            className="h-8 text-xs shrink-0"
            onClick={handleAction}
          >
            Connect
          </Button>
        )}
      </CardContent>
    </Card>
  );
};

// ─── Webhook Management Tab ───────────────────────────────────────────────────

interface WebhookEntry {
  id: string;
  url: string;
  events: string[];
  active: boolean;
}

const WEBHOOK_STORAGE_KEY = "rankora_webhooks";

function loadWebhooks(): WebhookEntry[] {
  try {
    return JSON.parse(localStorage.getItem(WEBHOOK_STORAGE_KEY) || "[]");
  } catch {
    return [];
  }
}

function saveWebhooks(hooks: WebhookEntry[]) {
  localStorage.setItem(WEBHOOK_STORAGE_KEY, JSON.stringify(hooks));
}

const EVENTS = [
  { value: "job.created", label: "Job Created" },
  { value: "ranking.completed", label: "Ranking Completed" },
  { value: "candidate.applied", label: "Candidate Applied" },
  { value: "candidate.rejected", label: "Candidate Rejected" },
  { value: "interview.scheduled", label: "Interview Scheduled" },
  { value: "stage.changed", label: "Stage Changed" },
];

function WebhooksTab() {
  const [webhooks, setWebhooks] = useState<WebhookEntry[]>(loadWebhooks);
  const [newUrl, setNewUrl] = useState("");
  const [newEvents, setNewEvents] = useState<string[]>(["ranking.completed"]);

  const toggleEvent = (value: string) => {
    setNewEvents((prev) =>
      prev.includes(value) ? prev.filter((e) => e !== value) : [...prev, value]
    );
  };

  const addWebhook = () => {
    const url = newUrl.trim();
    if (!url) {
      toast.error("Please enter a webhook URL");
      return;
    }
    try {
      new URL(url);
    } catch {
      toast.error("Please enter a valid URL (must start with https://)");
      return;
    }
    if (newEvents.length === 0) {
      toast.error("Select at least one event to subscribe to");
      return;
    }
    const entry: WebhookEntry = {
      id: crypto.randomUUID(),
      url,
      events: newEvents,
      active: true,
    };
    const updated = [...webhooks, entry];
    setWebhooks(updated);
    saveWebhooks(updated);
    setNewUrl("");
    setNewEvents(["ranking.completed"]);
    toast.success("Webhook endpoint added");
  };

  const removeWebhook = (id: string) => {
    const updated = webhooks.filter((w) => w.id !== id);
    setWebhooks(updated);
    saveWebhooks(updated);
    toast.success("Webhook removed");
  };

  const toggleActive = (id: string) => {
    const updated = webhooks.map((w) =>
