        {/* Page header */}
        <div className="mb-2">
          <h1 className="text-2xl font-semibold tracking-tight text-foreground">Integrations</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Connect your tools, manage API access, and configure webhooks.
          </p>
        </div>

        <Tabs defaultValue="integrations">
          <TabsList className="mt-6 mb-6">
            <TabsTrigger value="integrations">Integrations</TabsTrigger>
            <TabsTrigger value="webhooks">Webhooks</TabsTrigger>
            <TabsTrigger value="api">API</TabsTrigger>
          </TabsList>

          {/* ── Integrations tab ── */}
          <TabsContent value="integrations" className="space-y-5">
            {/* Search */}
            <div className="relative max-w-sm">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
              <Input
                placeholder="Search integrations..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-8 h-9 text-sm"
              />
            </div>

            {filtered.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 space-y-3">
                <div className="rounded-xl bg-muted/50 p-4">
                  <Search className="h-6 w-6 text-muted-foreground/50" />
                </div>
                <p className="text-sm font-medium">No integrations found</p>
                <p className="text-xs text-muted-foreground">Try a different search term</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                {filtered.map((integ) => (
                  <IntegrationCard key={integ.id} integration={integ} />
                ))}
              </div>
            )}
          </TabsContent>

          {/* ── Webhooks tab ── */}
          <TabsContent value="webhooks">
            <WebhooksTab />
          </TabsContent>

          {/* ── API tab ── */}
          <TabsContent value="api">
            <ApiTab />
          </TabsContent>
        </Tabs>
      </main>
    </SidebarLayout>
  );
};

export default Integrations;
